insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_7_v1'
from (values
('114.47.c.1.A',2,'In a Classical Languages class, a student answers either/or and who/what/where/when questions. These are examples of:','["simple question-and-answer practice", "advanced literary criticism", "map projection", "tax forms"]'::jsonb,0,'Level I uses basic question types.','original'),
('114.47.c.1.A',2,'Which question is an either/or question?','["When was it built?", "Is the city on a hill or on the coast?", "Who founded the city?", "What is the city called?"]'::jsonb,1,'Either/or questions offer two choices.','original'),
('114.47.c.1.B',1,'Memorized greetings in a classical language, such as a simple hello or goodbye, are used in:','["research papers", "scientific labs", "basic spoken or written exchanges", "financial reports"]'::jsonb,2,'Novice learners use memorized phrases.','original'),
('114.47.c.1.B',2,'Which is a memorized request a beginner might use?','["debating philosophy", "composing an epic", "analyzing meter", "asking politely for a book"]'::jsonb,3,'Memorized requests are everyday and simple.','original'),
('114.47.c.2.A',2,'A Level I student reads a short text adapted from ancient Rome. This is an example of using:','["culturally relevant print material", "a math word problem", "a periodic table", "a weather forecast"]'::jsonb,0,'Adapted texts introduce culture.','original'),
('114.47.c.2.A',3,'Which material is culturally relevant to a class studying ancient Greece?','["a sports score", "a short passage about daily life in Athens", "a cooking recipe about modern pasta", "a stock chart"]'::jsonb,1,'Relevant materials connect to the culture studied.','original'),
('114.47.c.2.B',2,'After reading a short passage, a Level I student identifies key words and details. This shows:','["creative writing", "mastery of meter", "basic comprehension", "advanced translation of epic poetry"]'::jsonb,2,'Key words and details show understanding.','original'),
('114.47.c.2.B',2,'Which is a key detail in a simple story about a Roman market?','["the printing press model", "the font size", "the page number", "what people bought and sold"]'::jsonb,3,'Details come from the story.','original'),
('114.47.c.2.C',3,'A learner meets an unfamiliar word in a text with a picture of a temple. The best strategy is to:','["use the picture and surrounding words to infer meaning", "guess randomly", "stop reading", "skip the passage"]'::jsonb,0,'Highly contextualized text allows inference.','original'),
('114.47.c.2.C',3,'Many English words come from Latin roots. Knowing this helps a learner:','["stop studying", "infer meanings of unfamiliar words", "forget vocabulary", "avoid reading"]'::jsonb,1,'Roots help inference.','original'),
('114.47.c.2.D',2,'A learner sees a picture of a Roman festival in a reading. What does the learner identify?','["a computer program", "a geometric proof", "a cultural practice", "a chemical formula"]'::jsonb,2,'Festivals are cultural practices.','original'),
('114.47.c.2.D',3,'Learning how ancient students were taught reading reveals:','["a modern law", "a science experiment", "a weather pattern", "a cultural practice of the ancient world"]'::jsonb,3,'Education practices are cultural.','original'),
('114.47.c.3.A',2,'Saying which character in a story you like best is an example of:','["expressing a preference", "translating a poem", "scanning meter", "writing a treaty"]'::jsonb,0,'Preferences are simple opinions.','original'),
('114.47.c.3.A',2,'Which sentence expresses a preference?','["The harbor was built long ago.", "I prefer the story about the harbor.", "Harbors exist.", "The harbor has twelve docks."]'::jsonb,1,'Preferences use I prefer or I like.','original'),
('114.47.c.3.B',2,'Describing a person in a reading with a mixture of words, phrases and short sentences is:','["a meter analysis", "a legal brief", "a simple description", "a complex essay"]'::jsonb,2,'Novice descriptions combine words and phrases.','original'),
('114.47.c.3.B',3,'Which is a simple description of an object in a story?','["a treatise on columns", "an essay on architecture", "a debate about stone", "a tall column made of white stone"]'::jsonb,3,'Simple descriptions use basic details.','original'),
('114.48.c.1.A',3,'At Level II, a student answers a question about daily life in Rome and adds a small detail. This is:','["simple elaboration", "avoidance", "copying", "silence"]'::jsonb,0,'Elaboration adds information.','original'),
('114.48.c.1.A',3,'Which answer shows simple elaboration to What did the Romans eat?','["I do not know.", "They ate bread and olives, often with wine.", "Food.", "Yes."]'::jsonb,1,'Elaboration adds detail.','original'),
('114.48.c.1.B',3,'At Level II, exchanging opinions about a story with simple support includes saying:','["Because.", "Character.", "I like this character because she is brave.", "Brave."]'::jsonb,2,'A reason supports the opinion.','original'),
('114.48.c.1.B',3,'Two students trade opinions about a hero from mythology and give a reason. This is:','["a spelling drill", "a dictionary lookup", "a map reading task", "an exchange of preferences with support"]'::jsonb,3,'Preference plus reason.','original'),
('114.48.c.1.C',3,'A Level II student tells a classmate what they should do before an exam using an appropriate expression. This is an example of:','["giving advice or direction", "describing weather", "analyzing a poem", "telling a legend"]'::jsonb,0,'Should and must express advice.','original'),
('114.48.c.1.C',3,'Which sentence tells someone what they must do?','["The passage has a title.", "You must read the passage again.", "The passage is old.", "I like the passage."]'::jsonb,1,'Must expresses necessity.','original'),
('114.48.c.2.A',3,'A learner reads a passage about a Greek theater. The material is described as culturally relevant because it:','["is unrelated to history", "is purely fictional", "connects to the culture being studied", "has no connection"]'::jsonb,2,'Relevance means connection.','original'),
('114.48.c.2.A',3,'Which source could be culturally relevant to a Level II classical class?','["a sports page", "a modern ad", "a phone manual", "an adapted passage on a Roman bath"]'::jsonb,3,'Relevant sources relate to the classical world.','original'),
('114.48.c.2.B',3,'Which task shows identifying main idea and details?','["telling what a passage is mostly about and naming two events", "counting words", "copying the first sentence", "skipping the text"]'::jsonb,0,'Main ideas and details show comprehension.','original'),
('114.48.c.2.C',3,'Using context to infer an unfamiliar word in a highly contextualized text means:','["stopping", "looking at nearby words and images for clues", "guessing without clues", "ignoring the sentence"]'::jsonb,1,'Context supports inference.','original'),
('114.48.c.2.C',3,'English words such as aquarium and aquatic share a root meaning water. Recognizing this helps a learner:','["skip reading", "avoid vocabulary", "infer related word meanings", "forget roots"]'::jsonb,2,'Word families help inference.','original'),
('114.48.c.2.D',3,'From a passage about Greek theater festivals, a learner identifies a cultural practice. This is:','["identifying chemical formulas", "identifying star charts", "identifying tax codes", "identifying cultural practices"]'::jsonb,3,'Festivals are practices.','original'),
('114.48.c.2.D',3,'A reading about public baths in Rome shows readers:','["how ancient people spent their daily lives", "how to measure rainfall", "how to program", "how to code"]'::jsonb,0,'Daily life is a cultural practice.','original'),
('114.48.c.3.A',3,'Expressing and supporting an opinion about a character means:','["reading silently", "giving a reason for the preference", "stating only the name", "copying a quote"]'::jsonb,1,'Support follows opinion.','original'),
('114.48.c.3.A',3,'Which written sentence expresses and supports an opinion?','["Wise.", "The hero.", "I think the hero is wise because he listens to advice.", "Hero."]'::jsonb,2,'A reason supports the opinion.','original'),
('114.48.c.3.B',3,'Describing a person or place with essential details means including:','["unrelated facts", "no detail", "every possible detail", "the most important facts"]'::jsonb,3,'Essential details are key facts.','original'),
('114.48.c.3.B',3,'Which description includes essential details of a temple?','["a marble temple with tall columns on a hill", "building", "a place", "a temple"]'::jsonb,0,'Details make a description clear.','original'),
('114.49.c.1.A',3,'At Level III a student responds to a question on a text with simple elaboration. This shows:','["avoidance", "building on a basic answer with added detail", "copying", "silence"]'::jsonb,1,'Elaboration deepens answers.','original'),
('114.49.c.1.A',3,'Which response shows elaboration to a question about a poem''s mood?','["Yes.", "Poem.", "The mood is sad because the speaker misses home.", "Sad."]'::jsonb,2,'A reason adds detail.','original'),
('114.49.c.1.B',3,'Exchanging opinions about a story with simple support in conversation means:','["only copying", "avoiding the topic", "only reciting a title", "stating a view and giving a reason"]'::jsonb,3,'Support makes opinions stronger.','original'),
('114.49.c.1.B',3,'Which statement exchanges a preference with support?','["I prefer the epic over the play because the adventure is exciting.", "Adventure.", "Play.", "Epic."]'::jsonb,0,'Preference plus because.','original'),
('114.49.c.1.C',3,'Telling someone what they should do with appropriate expressions is an example of:','["scanning verse", "giving advice or directions", "describing a map", "narrating history"]'::jsonb,1,'Should and must give advice.','original'),
('114.49.c.1.C',3,'Which sentence uses an appropriate expression for advice?','["I like vocabulary.", "The vocabulary is a list.", "You should review the vocabulary before the quiz.", "Quiz."]'::jsonb,2,'Should gives advice.','original'),
('114.49.c.2.A',4,'Culturally authentic materials in a Level III classical class include:','["modern slang", "only textbook exercises", "unrelated recipes", "original or lightly adapted ancient texts"]'::jsonb,3,'Authentic materials come from the ancient world.','original'),
('114.49.c.2.A',4,'Why use authentic texts at Level III?','["they show real language and cultural values", "they replace study", "they have no value", "they avoid culture"]'::jsonb,0,'Authentic texts reflect culture.','original'),
('114.49.c.2.B',4,'To paraphrase the main idea of a passage, a learner:','["skips it", "restates it in different words", "only underlines", "copies it exactly"]'::jsonb,1,'Paraphrasing shows understanding.','original'),
('114.49.c.2.B',4,'A supporting detail in a passage about a military campaign could be:','["the font", "the paper color", "a description of the army''s route", "the page margin"]'::jsonb,2,'Details support the main idea.','original'),
('114.49.c.2.C',4,'Analyzing authentic literature for stylistic features includes looking at:','["font size", "page count only", "binding style", "genre, literary devices and the author''s choices"]'::jsonb,3,'Style analysis looks at how an author writes.','original'),
('114.49.c.2.C',4,'A metaphor in ancient poetry is an example of:','["a literary device", "a measurement", "a map symbol", "a chemical term"]'::jsonb,0,'Metaphors are devices.','original'),
('114.49.c.2.D',4,'Inferring the meaning of a new word in a contextualized text relies on:','["random guessing", "context and knowledge of word parts", "ignoring clues", "skipping the sentence"]'::jsonb,1,'Inference uses multiple clues.','original'),
('114.49.c.2.D',4,'A learner knows a prefix and a root. Using them to understand a new word is:','["a pronunciation drill", "a copying task", "a word analysis strategy", "a spelling error"]'::jsonb,2,'Word parts help meaning.','original'),
('114.49.c.2.E',4,'Comparing how Greeks and Romans celebrated festivals is:','["naming rivers", "measuring angles", "comparing math results", "contrasting cultural practices"]'::jsonb,3,'Practices are compared.','original'),
('114.49.c.2.E',4,'A student notes similarities and differences between two ancient cultures'' education. This is:','["comparing and contrasting cultural practices", "skipping the reading", "ignoring sources", "copying vocabulary"]'::jsonb,0,'Comparison highlights likeness and difference.','original'),
('114.49.c.3.A',4,'Citing justification for an opinion using textual evidence means:','["stating a feeling only", "pointing to specific lines or details from the text", "repeating the question", "avoiding the text"]'::jsonb,1,'Evidence supports an opinion.','original'),
('114.49.c.3.A',4,'Which statement uses textual evidence?','["Storms exist.", "I like heroes.", "The hero is brave because the text says he faces the storm alone.", "The hero is brave."]'::jsonb,2,'Evidence from the text supports a claim.','original'),
('114.49.c.3.B',4,'Reading poetry aloud with attention to declamation involves:','["reading in a monotone", "speeding through", "ignoring punctuation", "paying attention to meter, meaning and expression"]'::jsonb,3,'Declamation brings out rhythm and meaning.','original'),
('114.49.c.3.B',4,'Why does meter matter when reading classical verse aloud?','["rhythm shapes the sound and the effect of the poem", "it hides meaning", "it has no effect", "it is only decoration"]'::jsonb,0,'Meter is central to verse.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
